//! Splitting a sector by a conserved circle charge.
//!
//! A one-parameter symmetry of the problem acts on the three tensor factors of a field b in (frame) (x) (gauge) (x) V:
//! by a rotation of the orthonormal frame (an isometry generated by `frame_gen` in the frame algebra), by a constant gauge
//! rotation (`gauge_gen` in the gauge algebra), and on V by the right action, rho(frame_gen). The charge is
//!
//!   Q = i (s_f A_f (x) 1 (x) 1 + s_g 1 (x) A_g (x) 1 + s_v 1 (x) 1 (x) rho(frame_gen)),
//!
//! with A_f = ad(frame_gen) in the orthonormal frame and A_g = ad(gauge_gen). Signs depend on conventions (left vs right,
//! active vs passive), so they are *fitted*: s_f = +1 and (s_g, s_v) chosen so that Q commutes with H and intertwines G
//! (Q G = G Q_param). The fit residual is reported, never assumed. Q is diagonalised factor by factor, so each charge
//! space has an exact product basis and the blocks of H, H + G G^*, and the gauge slice are computed blockwise.

use crate::linalg::{self, CMat};
use crate::sector::{HessianGauge, Sector};
use faer::Mat;
use std::collections::BTreeMap;

/// The generator of a circle symmetry, in coefficients of the frame basis X_a and of the gauge basis T_alpha.
#[derive(Clone, Debug)]
pub struct CircleGenerator {
    pub frame_gen: Vec<f64>,
    pub gauge_gen: Vec<f64>,
}

/// Charges are rounded to multiples of this before grouping (charges are half-integers for SU(2); any lattice finer
/// than the spacing works).
const CHARGE_QUANTUM: f64 = 1e-6;

/// Key of a charge value (rounded).
pub type ChargeKey = i64;

pub fn charge_key(q: f64) -> ChargeKey {
    (q / CHARGE_QUANTUM).round() as i64
}

pub fn charge_value(k: ChargeKey) -> f64 {
    k as f64 * CHARGE_QUANTUM
}

/// A sector split into charge blocks.
pub struct ChargeSplit {
    /// Fitted signs (s_g, s_v).
    pub signs: (f64, f64),
    /// max |[Q, H]| and max |Q G - G Q_param| at the fitted signs.
    pub commutator_residual: f64,
    pub intertwiner_residual: f64,
    /// Orthonormal field-space basis of each charge space (columns), keyed by charge.
    pub field_bases: BTreeMap<ChargeKey, CMat>,
    /// Orthonormal parameter-space basis (gauge (x) V) of each charge space.
    pub param_bases: BTreeMap<ChargeKey, CMat>,
}

/// Eigen-decomposition of the Hermitian matrix i * a (a anti-Hermitian / real antisymmetric).
fn charge_eig(a: &CMat) -> (Vec<f64>, CMat) {
    linalg::eigh(&linalg::scale(a, linalg::I))
}

fn kron_vec(a: &[f64], b: &[f64]) -> Vec<f64> {
    a.iter().flat_map(|x| b.iter().map(move |y| x + y)).collect()
}

fn group(charges: &[f64], basis: &CMat) -> BTreeMap<ChargeKey, CMat> {
    let mut idx: BTreeMap<ChargeKey, Vec<usize>> = BTreeMap::new();
    for (k, q) in charges.iter().enumerate() {
        idx.entry(charge_key(*q)).or_default().push(k);
    }
    idx.into_iter()
        .map(|(key, cols)| (key, Mat::from_fn(basis.nrows(), cols.len(), |i, j| basis[(i, cols[j])])))
        .collect()
}

impl ChargeSplit {
    /// Fit the signs and build the charge spaces for `sector` at the operators `hg`.
    pub fn new(sector: &Sector, hg: &HessianGauge, gen: &CircleGenerator) -> Self {
        let (n, r, d) = sector.dims();
        let s = sector.geo.sqrt_metric();
        // ad(frame_gen) on the frame algebra, in the orthonormal frame: (S A S^-1).
        let af_raw = sector.geo.frame.ad(&gen.frame_gen);
        let af = Mat::from_fn(n, n, |b, col| linalg::c(af_raw[b * n + col] * s[b] / s[col]));
        let ag = linalg::from_real(r, r, &sector.field.gauge.ad(&gen.gauge_gen));
        let mut rv = linalg::zeros(d, d);
        for (a, &w) in gen.frame_gen.iter().enumerate() {
            if w != 0.0 {
                rv = rv + linalg::scale(&sector.rep.mats[a], linalg::c(w));
            }
        }
        let (ir, id, ifr) = (linalg::eye(r), linalg::eye(d), linalg::eye(n));
        let qf = linalg::kron(&linalg::kron(&af, &ir), &id);
        let qg = linalg::kron(&linalg::kron(&ifr, &ag), &id);
        let qv = linalg::kron(&linalg::kron(&ifr, &ir), &rv);
        let pg = linalg::kron(&ag, &id);
        let pv = linalg::kron(&ir, &rv);
        let mut best: Option<(f64, f64, f64, f64)> = None;
        for sg in [1.0, -1.0] {
            for sv in [1.0, -1.0] {
                let q = linalg::scale(&(&qf + linalg::scale(&qg, linalg::c(sg)) + linalg::scale(&qv, linalg::c(sv))), linalg::I);
                let qp = linalg::scale(&(linalg::scale(&pg, linalg::c(sg)) + linalg::scale(&pv, linalg::c(sv))), linalg::I);
                let comm = linalg::max_abs(&linalg::commutator(&q, &hg.h));
                let inter = linalg::max_abs(&(&q * &hg.g - &hg.g * &qp));
                if best.map_or(true, |b| comm + inter < b.2 + b.3) {
                    best = Some((sg, sv, comm, inter));
                }
            }
        }
        let (sg, sv, comm, inter) = best.unwrap();
        let (cf, uf) = charge_eig(&af);
        let (cg, ug) = charge_eig(&linalg::scale(&ag, linalg::c(sg)));
        let (cv, uv) = charge_eig(&linalg::scale(&rv, linalg::c(sv)));
        let field_q = kron_vec(&kron_vec(&cf, &cg), &cv);
        let field_u = linalg::kron(&linalg::kron(&uf, &ug), &uv);
        let param_q = kron_vec(&cg, &cv);
        let param_u = linalg::kron(&ug, &uv);
        Self {
            signs: (sg, sv),
            commutator_residual: comm,
            intertwiner_residual: inter,
            field_bases: group(&field_q, &field_u),
            param_bases: group(&param_q, &param_u),
        }
    }

    pub fn charges(&self) -> Vec<f64> {
        self.field_bases.keys().map(|k| charge_value(*k)).collect()
    }

    /// The block V_q^H A V_q of a field-space operator.
    pub fn block(&self, a: &CMat, q: ChargeKey) -> CMat {
        let v = &self.field_bases[&q];
        linalg::adjoint(v) * a * v
    }

    /// Lowest eigenvalue of each block of a field-space operator, keyed by charge.
    pub fn block_minima(&self, a: &CMat) -> BTreeMap<ChargeKey, f64> {
        self.field_bases
            .keys()
            .map(|&q| (q, linalg::eigvalsh(&self.block(a, q)).first().copied().unwrap_or(f64::INFINITY)))
            .collect()
    }

    /// Spectrum of each block of a field-space operator.
    pub fn block_spectra(&self, a: &CMat) -> BTreeMap<ChargeKey, Vec<f64>> {
        self.field_bases.keys().map(|&q| (q, linalg::eigvalsh(&self.block(a, q)))).collect()
    }

    /// Gauge-orthogonal spectrum, blockwise: in each charge space, H on ker G_q^* with G_q = V_q^H G W_q.
    pub fn slice_block_spectra(&self, hg: &HessianGauge) -> BTreeMap<ChargeKey, Vec<f64>> {
        self.field_bases
            .iter()
            .map(|(&q, v)| {
                let hq = linalg::adjoint(v) * &hg.h * v;
                let spec = match self.param_bases.get(&q) {
                    Some(w) => {
                        let gq = linalg::adjoint(v) * &hg.g * w;
                        let (k, _) = linalg::cokernel(&gq, 1e-10);
                        linalg::compressed_eigvalsh(&hq, &k)
                    }
                    None => linalg::eigvalsh(&hq),
                };
                (q, spec)
            })
            .collect()
    }
}

/// All values of a keyed spectrum, sorted.
pub fn flatten(spectra: &BTreeMap<ChargeKey, Vec<f64>>) -> Vec<f64> {
    let mut v: Vec<f64> = spectra.values().flatten().copied().collect();
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    v
}
